const char *oui_vendor(const uint8_t mac[3])
{
    uint32_t key = ((uint32_t)mac[0] << 16) | (mac[1] << 8) | mac[2];
    size_t lo = 0, hi = sizeof(s_keys) / sizeof(s_keys[0]);
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (s_keys[mid] < key) {
            lo = mid + 1;
        } else if (s_keys[mid] > key) {
            hi = mid;
        } else {
            return s_names + s_name_off[mid];
        }
    }
    return NULL;
}
